class Solution {
    public int mostFrequent(int[] nums,int key){
        Map<Integer,Integer> frequency=new HashMap<>();
        int answer=0,best=0;
        for(int i=0;i+1<nums.length;i++)if(nums[i]==key){
            int count=frequency.merge(nums[i+1],1,Integer::sum);
            if(count>best){
                best=count;
                answer=nums[i+1];
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun mostFrequent(nums:IntArray,key:Int):Int{
        val frequency=HashMap<Int,Int>();
        var answer=0;
        var best=0;
        for(i in 0 until nums.lastIndex)if(nums[i]==key){
            val count=(frequency[nums[i+1]]?:0)+1;
            frequency[nums[i+1]]=count;
            if(count>best){
                best=count;
                answer=nums[i+1]
            }
        };
        return answer
    }
}

